	// reached your endpoint and which failed. It changes nothing. Needs the
	// permission to read webhooks.
	//
	// Refusals:
	// WEBHOOK_SUBSCRIPTION_NOT_FOUND — the subscription_id filter names no subscription of yours.
	// WEBHOOK_FILTER_INVALID — a filter value is not valid.
	// PAGINATION_CURSOR_INVALID — the page token is not one we gave you.
	// WEBHOOK_INVALID_INPUT — the page size is outside 0 to 200.
	ListDeliveries(context.Context, *connect.Request[v1.ListDeliveriesRequest]) (*connect.Response[v1.ListDeliveriesResponse], error)
	// Reads one delivery with every attempt and, while it is still kept, the
	// exact body that was sent. It changes nothing. Needs the permission to read
	// webhooks.
	//
	// Refusals:
	// WEBHOOK_DELIVERY_NOT_FOUND — no such delivery on your account.
	GetDelivery(context.Context, *connect.Request[v1.GetDeliveryRequest]) (*connect.Response[v1.GetDeliveryResponse], error)
